 parts[i] = parts[i].trim();
}

// Assign values
outputs.hotel_name = parts.length > 0 ? parts[0] : '';
outputs.hotel_city = parts.length > 1 ? parts[1] : '';
outputs.hotel_state = parts.length > 2 ? parts[2] : '';
outputs.hotel_country = parts.length > 3 ? parts[3] : '';
})()
